/**
 * Environment files in project workspaces: a list for the release, and the
 * removal of the ones Backenly wrote.
 *
 * POST /api/database/setup-workspace used to write a `.env` holding a database
 * connection string into a project's workspace, and the files sync copied it
 * into workspace_files. Neither happens now, and no workspace route serves an
 * environment file. This lists the copies made before that, on disk and in the
 * database, and with --apply removes the ones Backenly wrote (they start with
 * "# Auto-generated by Backenly"). Any other environment file is listed for a
 * person to decide. Contents are never printed. The logic is
 * lib/workspace/env-files.ts.
 *
 * Run it with the web service's environment, where WORKSPACE_DIR is mounted,
 * in every region.
 *
 *   npx tsx scripts/remove-workspace-env-files.ts            # list, change nothing
 *   npx tsx scripts/remove-workspace-env-files.ts --apply    # remove the ones Backenly wrote
 */

import { prisma } from '@/lib/db/prisma'
import { findWorkspaceEnvFiles, removeBackenlyEnvFiles } from '@/lib/workspace/env-files'
import { workspaceRoot } from '@/lib/workspace/paths'

async function main(): Promise<void> {
  const apply = process.argv.includes('--apply')
  const found = await findWorkspaceEnvFiles()

  const count = (where: 'disk' | 'database', backenly: boolean) =>
    found.filter((f) => f.where === where && f.writtenByBackenly === backenly).length

  console.log(`Environment files in project workspaces (workspace root ${workspaceRoot()}); contents not shown`)
  console.log(`  on disk:     ${count('disk', true)} written by Backenly, ${count('disk', false)} other`)
  console.log(`  in database: ${count('database', true)} written by Backenly, ${count('database', false)} other`)

  const other = found.filter((f) => !f.writtenByBackenly)
  if (other.length) {
    console.log('\nOther environment files, left in place (no workspace route serves them):')
    for (const f of other) console.log(`  ${f.where.padEnd(9)} ${f.projectId}  ${f.file}`)
  }

  const backenly = found.filter((f) => f.writtenByBackenly).length
  if (!apply) {
    console.log(backenly ? `\nRun with --apply to remove the ${backenly} written by Backenly.` : '\nNothing to remove.')
    return
  }
  const removed = await removeBackenlyEnvFiles(found)
  console.log(`\nRemoved ${removed.files} file(s) from disk and ${removed.rows} row(s) from workspace_files.`)
}

main()
  .catch((error) => {
    console.error(error)
    process.exitCode = 1
  })
  .finally(() => prisma.$disconnect())
